function ChapterMoodPlane:InitPlane(roleId, max, min)
    self.range = max - min
    self.max = max
    self.min = min
    self.roleId = roleId
    self.ImgHead.OnFinish = function()
        KTool.SetActive(self.ImgHead, true)
    end
    KTool.SetActive(self.ImgHead, false)
    self.ImgHead:LoadSprite(string.format(NewChapterConstants.MoodHeadPath, roleId))
    self:SetValue(0, 0)
    KTool.SetActive(self.controller.gameObject, true)
end

function ChapterMoodPlane:SetValue(value, addValue)
    local needAnim = addValue ~= 0
    printInfo("SetValue %d %d", value, addValue)
    local toValue = (value - self.min) / self.range
    printInfo("to value %f", toValue)
    self.TxtNumber.text = value
    if needAnim then
        if not isNull(self.tween) then
            self.tween:Complete()
        end
        self.tween = self.Slider:DOValue(toValue, 0.5):SetEase(Ease.OutBack):OnComplete(function() 
            self.tween = nil
        end)
    else
        self.Slider.value = toValue
    end
    
end

function ChapterMoodPlane:OnDestroy()
    if not isNull(self.tween) then
        self.tween:Complete()
        self.tween = nil
    end
    
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return ChapterMoodPlane